import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第114章 一个阶层","description":"","frontmatter":{},"headers":[],"relativePath":"第114章_一个阶层.md","filePath":"第114章_一个阶层.md"}'),_={name:"第114章_一个阶层.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第114章-一个阶层" tabindex="-1">第114章 一个阶层 <a class="header-anchor" href="#第114章-一个阶层" aria-label="Permalink to &quot;第114章 一个阶层&quot;">​</a></h1><p>08:51</p><p>她接着讲了一件我没想到的事。</p><p>她说：我跟不是一个阶层。</p><p>她说：我讲这个不是我要往下看你。</p><p>她说：我是讲我抬头看你的时候我自己难受。</p><p>我说：我这儿你抬什么头。</p><p>她说：你今天早上在你妈煮粥的厨房里，跟我讲&quot;那我改什么&quot;。</p><p>她说：你知不知道这句是什么。</p><p>她说：这是一句有钱人讲的话。</p><p>她说：这是一个&quot;我后面有人接着&quot;的人才讲得出来的话。</p><p>她说：你问你改什么，是因为你改了以后你明天还是那个人。</p><p>她说：你改不改，你那个单位在。</p><p>她说：你改不改，你妈那碗粥在。</p><p>她说：你改不改，你今年过年那个屋还是你的。</p><p>她说：我今天早上三点了我睡不着，我算的是我下个月房租两千二。</p><p>她说：我算的是那个展我要不要自己出。</p><p>她说：我算的是那个四千七我现在要还。</p><p>她说：我算的是我妈那年给我的那张卡，我现在用掉了两万四。</p><p>她说：我用掉了，我要还。</p><p>她说：我要是还不上，我这辈子在她面前就低一头。</p><p>她说：你今天早上跟我讲&quot;那我改什么&quot;。</p><p>她说：我要是你，我不敢讲这句。</p><p>08:55</p><p>我说：那你今天想我怎么讲。</p><p>她说：你不用讲。</p><p>我说：我在问。</p><p>她说：你今天问我这个问题，你就还是在要一个我能答的东西。</p><p>她说：我要是答了，我就变成给你派活。</p><p>她说：你给我派活这件事我们两个今年已经做了两年。</p><p>她说：一箱五十件，一单你一块五，我八块。</p><p>她说：我们两个现在是这个关系。</p><p>她说：我那天把这个讲成&quot;这样我才不慌&quot;。</p><p>她说：我今天跟你讲，我不慌是因为这个里面有钱。</p><p>她说：钱这个东西把我们的事变成一件可以解释的事。</p><p>她说：客人投诉，我们两个一起对账单，我们不用讲别的。</p><p>她说：她漏发了，我们对一个二十四块，我们不用讲我们。</p><p>她说：我今天算了一下，我们两个上一次不讲钱、不讲货、不讲行程，坐下来讲话是哪一天。</p><p>我说：二月。</p><p>她说：不对。</p><p>她说：是去年十月。</p><p>她说：十月十七，你跟我讲你那个猫吐了。</p><p>她说：你那天讲了二十分钟那只猫。</p><p>她说：那天我们两个没讲任何一件要办的事。</p><p>她说：我那天晚上回去画图画到一点，我很高兴。</p><p>她说：我那天高兴完以后我第二天早上起来，我心里第一句话是：这样不行。</p><p>09:00</p><p>我说：你为什么不行。</p><p>她说：因为那只猫我讲完，我要开始想我自己。</p><p>她说：我想我自己我要是想出一个&quot;我过得挺好&quot;，我那天晚上就要问你一句你在哪儿。</p><p>她说：我要是问出那一句，我就得等你答。</p><p>她说：我等你的时候我不能画图。</p><p>她说：我一天不能画八个小时，我这一周就废。</p><p>她说：我这一周废了，我这一个月就废。</p><p>她说：我这一个月废了，我要跟我妈讲我为什么没钱。</p><p>她说：我今天夜里十二点坐在床上，我把这一串从&quot;那只猫&quot;一路算到&quot;我妈&quot;。</p><p>她说：我算完我发现我们两个连一只猫都讲不起。</p><p>她说：这不是谁的错。</p><p>她说：这是我们两个的经济状况决定的。</p><p>她说：我讲这个话很难听。</p><p>她说：我今天不想讲好听的。</p><p>09:04</p><p>我说：那我要是有钱呢。</p><p>她说：你今天讲这句，你今天晚上就会后悔。</p><p>我说：为什么。</p><p>她说：因为你现在会讲这句，是因为你觉得这是你的问题。</p><p>她说：这不是你的问题。</p><p>她说：你今年三十一，你有一间屋，你有一个妈给你煮粥，你上班有排班，你去年腰疼你请了三天假工资没扣。</p><p>她说：你在我眼里是安全的人。</p><p>她说：你从来不用担心下个月。</p><p>她说：这不是你能改的。</p><p>她说：我要是跟你说&quot;我有钱就行&quot;，我是在拿你比我有的那一面。</p><p>她说：我不干这个。</p><p>她说：我今天讲的这些不是要你觉得你不够。</p><p>她说：我今天讲的是我不够，而我这个不够是我这一辈子挣出来的，不是我要来的。</p><p>她说：我不要你补。</p><p>她说：我今年算过，我要是让你补我一次，我下一次开口就要小十二个月。</p><p>她说：我不想再等十二个月。</p><p>09:06</p><p>我说：你今天讲这个，我听着很难受。</p><p>她说：我今天不讲你听着难受的东西，我今天讲了你就只记得你难受。</p><p>她说：你今天难受完你明天就只记得我狠。</p><p>她说：我不要你记得我狠。</p><p>我说：那你要你记得什么。</p><p>她说：我要你记得我今天夜里十二点坐在床上，同时算着五件事。</p><p>她说：这五件里你是第四件。</p><p>我说：前五件是什么。</p><p>她说：房租，体检，图，你，我妈今天那个降压药她忘吃了。</p><p>她说：我今天早上三点想起来她没吃药，我下去给她倒了水。</p><p>她说：我在那个走廊上站着，我拿那个水杯。</p><p>她说：我那时候想，我今天要是不上来，我今天早上可以跟你讲一句别的。</p><p>她说：我今天早上可以讲一句“我今天看见一个卖鸡蛋的”，你听见的是我今天跟一个人讲话。</p><p>她说：我没讲。</p><p>她说：因为我今天拿那个水杯的时候，我心里算的是我下个月房租。</p><p>她说：我今天夜里零点十二拿着一杯水坐在床上，我打的是“我基本上并不喜欢你”。</p><p>她说：我那天晚上在手机上存了一句“我今天看见有人卖鸡蛋”。</p><p>她说：我今天早上把那句删了。</p><p>她说：我今天删那句的时候我心里很清楚，我删的不是那一句。</p><p>她说：我删的是我今年二月二十号那个包。</p><p>09:09</p><p>我说：那你今天要什么。</p><p>她说：我今天要跟你把二月二十号取消。</p><p>她说：我把那张票今天上午退。</p><p>她说：我要是退了，我下午两点能睡着。</p><p>她说：我三点十二讲这些，我全部是为了让我今天下午能把那张票退掉。</p><p>她说：我昨天夜里在退票那个页面站了两个钟头。</p><p>她说：我站在那儿我退不了。</p><p>她说：我退不了是因为我要是不退我要来，我要来我今天要跟你讲一句&quot;我来了&quot;。</p><p>她说：我讲&quot;我来了&quot;之前，我要是不知道你心里怎么想，我会一直站在那个页面上。</p><p>她说：我今天早上把我要讲的都讲了。</p><p>她说：你现在可以讲一句你要不要我来。</p><p>她说：我要这一句。</p><p>她说：我要这一句我才退得了。</p>',113)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
